/**
 * MessageModel — public.messages.
 *
 * Notes:
 *   - `role` is a real column, constrained to `'user' | 'assistant'`.
 *     Callers must pass `role` explicitly on insert.
 *   - `response_options`, `thinking_content`, `tool_activity`, and
 *     `injected_during_run` live inside the `metadata` jsonb column.
 *     We fold on write and unfold on read so consumers see them as
 *     top-level `MessageRow` fields.
 *   - `user_id` is an optional column.
 *   - `search_text` is generated by the database from content and
 *     search_entity_terms; it cannot be written directly.
 *
 * Extends the base Model with message-specific query methods
 * (thread listing, recent descending).
 */

import { generateId } from '@snaglet/shared/utils';
import { NODE_KIND } from '@snaglet/shared/constants';
import type { RunErrorKind } from '@snaglet/shared/types';
import { Model } from '@snaglet/db/Model';
import { Nodes, type NodeRunner } from '@snaglet/db/tables/nodes';

/**
 * Roles persisted in public.messages.role. `'system'` is intentionally absent
 * here — it's not allowed by the DB CHECK constraint.
 * If you need to *consume* a wider role set (e.g. LLM provider adapters that
 * also emit `'system'` for injected prompts), define that wider type at the
 * boundary, not on the DB row.
 */
export type MessageRole = 'user' | 'assistant';
/**
 * `thread_event` — author-less machine narration of thread-variable state
 * (roster/dispatch-mode changes, the turn-zero "thread started" line), kept
 * in the transcript so the system prompt stays cacheable. They are role='user'
 * with no author (user_id and agent_id both null) and replay as plain text
 * lines; see `createEvent`.
 */
type MessageType = 'message' | 'question' | 'thread_event';

/** Token usage an assistant message carries for the run that produced it. */
interface MessageUsage {
  inputTokens?: number;
  outputTokens?: number;
  contextWindowTokens?: number;
  /** Times the run compacted its own context mid-run (absent when it never did). */
  runCompactions?: number;
}

export interface MessageRow {
  id: string;
  threadId: string;
  agentId: string | null;
  /** public.messages.user_id is text (FK to public.users.id). */
  userId: string | null;
  role: MessageRole;
  content: string;
  messageType: MessageType;
  resolved: boolean;
  createdAt: string;
  /** Optional response option metadata, surfaced from metadata jsonb. */
  responseOptions: unknown | null;
  /** Optional thinking-trace content, surfaced from metadata jsonb. */
  thinkingContent: string | null;
  /** Optional tool activity payload, surfaced from metadata jsonb. */
  toolActivity: unknown | null;
  /** Whether the message was injected mid-run, surfaced from metadata jsonb. */
  injectedDuringRun: boolean;
  /** Cumulative token usage for the run that produced this message. */
  usage: MessageUsage | null;
  /** Run that produced this message — null for user messages. FK → runs.id. */
  runId: string | null;
  /**
   * Run-failure descriptor surfaced from metadata.run_error. Set when the
   * message was authored by `persistRunErrorMessage` after a mid-stream
   * failure; null on any normal reply. UI uses this to render the row as
   * a distinct error bubble.
   */
  runError: RunErrorMeta | null;
  /**
   * Per-agent opening-message context packs, surfaced read-only from
   * `metadata.contextPacks` (agentId → rendered pack text). Written write-once by
   * `setContextPackOnce` during the opener turn; the UI renders it as the
   * "injected context" disclosure on the user bubble. Read-only-surfaced (like
   * `runError`), not in METADATA_SURFACED_KEYS, so the fold-on-write path never
   * touches it.
   */
  contextPacks: Record<string, string> | null;
  /**
   * Outbound-linter attribution, surfaced read-only from
   * `metadata.linter_target_agent_id`. Set on the injected correction message
   * naming the agent whose reply referenced unverified ids. The UI keys its
   * small linter meta line off this plus `fabricatedIds` — without both, the
   * row is indistinguishable from an ordinary mid-run user message.
   * Read-only-surfaced (like `runError`), not in METADATA_SURFACED_KEYS.
   */
  linterTargetAgentId: string | null;
  /**
   * Unverified workspace ids detected in the linted reply, surfaced read-only
   * from `metadata.fabricated_ids`. Carried as metadata rather than rewritten
   * into message content so the provider cache prefix stays byte-stable.
   */
  fabricatedIds: string[] | null;
  /** Raw metadata blob (includes the surfaced fields above plus anything else). */
  metadata: Record<string, unknown> | null;
  externalSender: { memberId: string; name: string } | null;
  /**
   * Raw label for a `from` param that didn't resolve to a known agent or
   * member/user (see resolveFromSender.ts). A real column
   * (public.messages.external_sender), distinct from `externalSender` above,
   * which is the connection-level MCP-caller attribution folded into metadata.
   * Null whenever `from` resolved to a real identity, or wasn't supplied.
   */
  externalSenderLabel: string | null;
  /**
   * Agent-private target, a real column (public.messages.visible_to_agent_id).
   * NULL = visible to everyone (the default for every normal message). When
   * set, the message is rendered into the payload only for the agent whose id
   * matches (see replayAssembly buildReplay).
   */
  visibleToAgentId: string | null;
}

/**
 * Structured shape for `metadata.run_error`. Kept narrow on purpose — the
 * value travels into agent context windows on the next turn, so anything
 * here must be safe-to-show and free of stack traces / paths / secrets.
 */
interface RunErrorMeta {
  kind: RunErrorKind;
  summary: string;
  provider?: string | null;
  modelId?: string | null;
  agentName?: string | null;
}

interface MessageInsert {
  id?: string;
  threadId: string;
  /**
   * Authorship role. Required — callers express intent explicitly, never
   * inferred from `agentId`/`userId` presence. Must agree with the populated
   * authorship field (DB CHECK `messages_role_matches_author` enforces this):
   *   role: 'user'      requires userId  to be set, agentId null
   *   role: 'assistant' requires agentId to be set, userId  null
   */
  role: MessageRole;
  agentId?: string | null;
  userId?: string | null;
  content: string;
  messageType?: MessageType;
  resolved?: boolean;
  responseOptions?: unknown | null;
  thinkingContent?: string | null;
  toolActivity?: unknown | null;
  injectedDuringRun?: boolean;
  usage?: MessageUsage | null;
  runId?: string | null;
  metadata?: Record<string, unknown> | null;
  /** See MessageRow.externalSenderLabel. Written verbatim to the real
   *  `external_sender` column via the columnMap override below — not folded
   *  into metadata. */
  externalSenderLabel?: string | null;
}

interface MessageUpdate {
  content?: string;
  resolved?: boolean;
  responseOptions?: unknown | null;
  thinkingContent?: string | null;
  toolActivity?: unknown | null;
  injectedDuringRun?: boolean;
  usage?: MessageUsage | null;
  runId?: string | null;
  metadata?: Record<string, unknown> | null;
}

/**
 * Keys that live inside metadata jsonb but are surfaced top-level on
 * MessageRow. Writes set the top-level camelCase field; foldMetadata translates
 * to the snake_case jsonb key. Reads unfold in `transformRow`.
 *
 * `runError` is not in this list: it is read-only-surfaced. Writers set
 * `metadata.run_error` directly with the snake_case shape so the helper code
 * (see persistRunErrorMessage.ts) stays explicit about the wire shape, and the
 * read-side normalizer translates snake→camel for the MessageRow consumer.
 */
const METADATA_SURFACED_KEYS = [
  'responseOptions',
  'thinkingContent',
  'toolActivity',
  'injectedDuringRun',
  'usage',
] as const;

/** snake_case equivalents used as jsonb keys inside metadata. */
const METADATA_JSON_KEYS: Record<(typeof METADATA_SURFACED_KEYS)[number], string> = {
  responseOptions: 'response_options',
  thinkingContent: 'thinking_content',
  toolActivity: 'tool_activity',
  injectedDuringRun: 'injected_during_run',
  usage: 'usage',
};

/**
 * Translate the snake_case `metadata.run_error` jsonb shape into the
 * camelCase `RunErrorMeta` consumer shape. Returns null when the value is
 * missing or doesn't have the minimum required (kind + summary) fields.
 */
/**
 * Read-only surface for `metadata.contextPacks` (agentId → pack text). Keeps
 * only string values so a malformed blob can't leak non-string shapes onto the
 * MessageRow consumer. Returns null when absent or empty.
 */
function unfoldContextPacks(raw: unknown): Record<string, string> | null {
  if (!raw || typeof raw !== 'object') return null;
  const out: Record<string, string> = {};
  for (const [agentId, pack] of Object.entries(raw as Record<string, unknown>)) {
    if (typeof pack === 'string' && pack.length > 0) out[agentId] = pack;
  }
  return Object.keys(out).length > 0 ? out : null;
}

function unfoldRunError(raw: unknown): RunErrorMeta | null {
  if (!raw || typeof raw !== 'object') return null;
  const r = raw as Record<string, unknown>;
  const kind = r.kind;
  const summary = r.summary;
  if (typeof kind !== 'string' || typeof summary !== 'string') return null;
  return {
    kind: kind as RunErrorMeta['kind'],
    summary,
    provider: (r.provider as string | null | undefined) ?? null,
    modelId: (r.model_id as string | null | undefined) ?? null,
    agentName: (r.agent_name as string | null | undefined) ?? null,
  };
}

class MessageModelClass extends Model<MessageRow, MessageInsert, MessageUpdate> {
  constructor() {
    super({
      table: 'messages',
      primaryKey: 'id',
      updatedAtColumn: null,
      columnMap: {
        threadId: 'thread_id',
        agentId: 'agent_id',
        userId: 'user_id',
        messageType: 'message_type',
        runId: 'run_id',
        // Distinct JS-side name from the metadata-folded `externalSender`
        // field (see MessageRow doc comments) so the two mechanisms never
        // collide on read or write.
        externalSenderLabel: 'external_sender',
        // Agent-private target. Real column; base transformRow maps it
        // camelCase automatically once projected in messageSelect below.
        visibleToAgentId: 'visible_to_agent_id',
      },
    });
  }

  /**
   * Explicit column projection for the message row shape.
   */
  private get messageSelect(): string {
    return `
      SELECT
        m.id, m.thread_id, m.user_id, m.agent_id, m.role,
        m.content, m.message_type, m.resolved, m.metadata, m.run_id,
        m.created_at, m.external_sender, m.visible_to_agent_id
      FROM ${this.qualifiedTable} m
    `.trim();
  }

  /**
   * Override row transform to unfold metadata jsonb into top-level surfaced
   * keys. `role` is not synthesized here — it's a real
   * column on public.messages and flows through the base
   * Model's column-map handling automatically.
   */
  protected transformRow<T>(row: Record<string, unknown> | null | undefined): T | null {
    const mapped = super.transformRow<MessageRow & Record<string, unknown>>(row);
    if (!mapped) return null;

    // Unfold metadata surfaced keys.
    const meta = (mapped.metadata ?? null) as Record<string, unknown> | null;
    mapped.responseOptions = meta?.[METADATA_JSON_KEYS.responseOptions] ?? null;
    mapped.thinkingContent =
      (meta?.[METADATA_JSON_KEYS.thinkingContent] as string | undefined) ?? null;
    mapped.toolActivity = meta?.[METADATA_JSON_KEYS.toolActivity] ?? null;
    mapped.injectedDuringRun =
      (meta?.[METADATA_JSON_KEYS.injectedDuringRun] as boolean | undefined) ?? false;
    mapped.usage = (meta?.[METADATA_JSON_KEYS.usage] as MessageRow['usage'] | undefined) ?? null;
    mapped.runError = unfoldRunError(meta?.['run_error']);
    mapped.contextPacks = unfoldContextPacks(meta?.['contextPacks']);
    mapped.externalSender =
      (meta?.['externalSender'] as MessageRow['externalSender'] | undefined) ?? null;
    // Linter attribution: written as snake_case metadata by the outbound
    // linter (finalReply.ts / utteranceMessages.ts) and unfolded here so the
    // history read path matches the socket broadcast shape.
    mapped.linterTargetAgentId = (meta?.['linter_target_agent_id'] as string | undefined) ?? null;
    mapped.fabricatedIds = Array.isArray(meta?.['fabricated_ids'])
      ? (meta['fabricated_ids'] as string[])
      : null;

    return mapped as T;
  }

  /**
   * Fold surfaced keys into a metadata jsonb payload before insert/update.
   * Mutates a shallow copy; returns input shape minus surfaced keys, with
   * metadata merged.
   */
  private foldMetadata<T extends Record<string, unknown>>(
    input: T
  ): Omit<T, (typeof METADATA_SURFACED_KEYS)[number]> & {
    metadata?: Record<string, unknown> | null;
  } {
    const out: Record<string, unknown> = { ...input };
    const meta: Record<string, unknown> = {
      ...((input.metadata ?? {}) as Record<string, unknown>),
    };
    let touched = false;
    for (const key of METADATA_SURFACED_KEYS) {
      if (key in out) {
        const jsonKey = METADATA_JSON_KEYS[key];
        const v = out[key];
        if (v === undefined || v === null) {
          delete meta[jsonKey];
        } else {
          meta[jsonKey] = v;
        }
        delete out[key];
        touched = true;
      }
    }
    if (touched) {
      out.metadata = meta;
    }
    // public.messages.metadata is `jsonb NOT NULL DEFAULT '{}'`. An explicit
    // `metadata: null` from a caller (or a fold that empties the object) must
    // serialize as `{}`, never SQL NULL — otherwise the INSERT/UPDATE violates
    // the not-null constraint. Leave `undefined` (field absent) alone so updates
    // that don't touch metadata keep the existing value.
    if (out.metadata === null) {
      out.metadata = {};
    }
    return out as Omit<T, (typeof METADATA_SURFACED_KEYS)[number]> & {
      metadata?: Record<string, unknown> | null;
    };
  }

  /** List all messages in a thread by the canonical oldest-first keyset. */
  async listByThreadId(threadId: string): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `${this.messageSelect} WHERE m.thread_id = $1 ORDER BY m.created_at ASC, m.id ASC`,
      [threadId]
    );
  }

  /**
   * Append-only perception slice: messages from a
   * start offset forward, ascending — the offset message itself included.
   * Returns [] when the offset message no longer exists in this thread;
   * callers treat that as "no offset" and re-anchor.
   */
  async listByThreadFromMessage(
    threadId: string,
    fromMessageId: string,
    limit: number
  ): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `${this.messageSelect}
        WHERE m.thread_id = $1
          AND (m.created_at, m.id) >= (
            SELECT m2.created_at, m2.id FROM ${this.qualifiedTable} m2
             WHERE m2.id = $2 AND m2.thread_id = $1
          )
        ORDER BY m.created_at ASC, m.id ASC
        LIMIT $3`,
      [threadId, fromMessageId, limit]
    );
  }

  /**
   * Load the most recent N messages for a thread (ordered oldest-first).
   * Use this instead of listByThreadId when full history is not needed.
   */
  async listRecentByThreadId(threadId: string, limit: number): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `SELECT * FROM (
         ${this.messageSelect}
         WHERE m.thread_id = $1
         ORDER BY m.created_at DESC
         LIMIT $2
       ) sub
       ORDER BY created_at ASC`,
      [threadId, limit]
    );
  }

  /** Latest page, or a page before a stable id cursor (a timestamp cursor is also accepted). */
  async listForThreadRead(
    threadId: string,
    opts: { limit: number; before?: string; beforeId?: string }
  ): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `SELECT * FROM (
         ${this.messageSelect}
         WHERE m.thread_id = $1
           AND ($4::text IS NULL OR (m.created_at, m.id) < (
             SELECT created_at, id FROM public.messages WHERE id = $4 AND thread_id = $1
           ))
           AND ($4::text IS NOT NULL OR $2::timestamptz IS NULL OR m.created_at < $2)
         ORDER BY m.created_at DESC, m.id DESC
         LIMIT $3
       ) sub
       ORDER BY created_at ASC, id ASC`,
      [threadId, opts.before ?? null, opts.limit, opts.beforeId ?? null]
    );
  }

  /**
   * Load up to `limit` messages strictly after the given (created_at, id)
   * cursor, oldest-first. Companion to `listForThreadRead` for forward
   * pagination — used by the chat view when the user opened to a windowed
   * chunk (e.g. via search) and scrolls forward toward the live tail.
   */
  async listAfter(
    threadId: string,
    opts: { limit: number; afterCreatedAt: string; afterId: string }
  ): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `${this.messageSelect}
       WHERE m.thread_id = $1
         AND (m.created_at, m.id) > (COALESCE(
           (SELECT created_at FROM public.messages WHERE id = $3 AND thread_id = $1), $2::timestamptz
         ), $3)
       ORDER BY m.created_at ASC, m.id ASC
       LIMIT $4`,
      [threadId, opts.afterCreatedAt, opts.afterId, opts.limit]
    );
  }

  /**
   * Whether the thread has any message with (created_at, id) strictly less
   * than the given cursor. Powers the chat view's "Load more" button visibility.
   */
  async hasOlderThan(
    threadId: string,
    cursor: { createdAt: string; id: string }
  ): Promise<boolean> {
    const row = await this.queryOne<{ exists: boolean }>(
      `SELECT EXISTS (
         SELECT 1 FROM public.messages
         WHERE thread_id = $1
           AND (created_at, id) < (COALESCE(
             (SELECT created_at FROM public.messages WHERE id = $3 AND thread_id = $1), $2::timestamptz
           ), $3)
       ) AS exists`,
      [threadId, cursor.createdAt, cursor.id]
    );
    return row?.exists === true;
  }

  /** Whether the thread has any message strictly after the given cursor. */
  async hasNewerThan(
    threadId: string,
    cursor: { createdAt: string; id: string }
  ): Promise<boolean> {
    const row = await this.queryOne<{ exists: boolean }>(
      `SELECT EXISTS (
         SELECT 1 FROM public.messages
         WHERE thread_id = $1
           AND (created_at, id) > (COALESCE(
             (SELECT created_at FROM public.messages WHERE id = $3 AND thread_id = $1), $2::timestamptz
           ), $3)
       ) AS exists`,
      [threadId, cursor.createdAt, cursor.id]
    );
    return row?.exists === true;
  }

  /**
   * Fetch a window of messages centered on an anchor message: up to `before`
   * messages immediately preceding it and up to `after` immediately following
   * it (in thread order), plus the anchor itself. Ordering matches
   * listForThreadRead: (m.created_at, m.id). The total returned is capped at
   * `cap` (default 50): if before+after+1 would exceed the cap, the `after`
   * side is trimmed first, then the `before` side, so the anchor is always
   * included. Returns rows oldest-first. Returns null if the anchor message
   * does not exist.
   */
  async getContextWindow(
    messageId: string,
    opts: { before: number; after: number; cap?: number }
  ): Promise<{ anchor: MessageRow; messages: MessageRow[] } | null> {
    const cap = opts.cap ?? 50;
    // Anchor must be included, so the surrounding budget is cap - 1.
    const surroundBudget = Math.max(0, cap - 1);
    let before = Math.max(0, Math.floor(opts.before));
    let after = Math.max(0, Math.floor(opts.after));
    // Trim to fit the cap: anchor always wins, then trim `after`, then `before`.
    if (before + after > surroundBudget) {
      const overflow = before + after - surroundBudget;
      const trimAfter = Math.min(after, overflow);
      after -= trimAfter;
      const stillOver = overflow - trimAfter;
      before -= Math.min(before, stillOver);
    }

    const anchor = await this.queryOne<MessageRow>(`${this.messageSelect} WHERE m.id = $1`, [
      messageId,
    ]);
    if (!anchor) return null;

    // Pull `before` rows strictly preceding the anchor (newest-first, then re-sort).
    const beforeRows =
      before > 0
        ? await this.query<MessageRow>(
            `SELECT * FROM (
               ${this.messageSelect}
               WHERE m.thread_id = $1
                 AND (m.created_at, m.id) < (COALESCE(
                   (SELECT created_at FROM public.messages WHERE id = $3 AND thread_id = $1), $2::timestamptz
                 ), $3)
               ORDER BY m.created_at DESC, m.id DESC
               LIMIT $4
             ) sub
             ORDER BY created_at ASC, id ASC`,
            [anchor.threadId, anchor.createdAt, anchor.id, before]
          )
        : [];

    // Pull `after` rows strictly following the anchor (oldest-first).
    const afterRows =
      after > 0
        ? await this.query<MessageRow>(
            `${this.messageSelect}
             WHERE m.thread_id = $1
               AND (m.created_at, m.id) > (COALESCE(
                 (SELECT created_at FROM public.messages WHERE id = $3 AND thread_id = $1), $2::timestamptz
               ), $3)
             ORDER BY m.created_at ASC, m.id ASC
             LIMIT $4`,
            [anchor.threadId, anchor.createdAt, anchor.id, after]
          )
        : [];

    const messages = [...beforeRows, anchor, ...afterRows];
    return { anchor, messages };
  }

  /**
   * Get the most recent message in a thread. Ordered by the same composite
   * `(created_at, id)` keyset that `listAfter` / `getContextWindow` page on, so
   * the "last row" is the deterministic keyset maximum. Without the `id`
   * tiebreaker, two head rows sharing a `created_at` could return the lower-id
   * sibling, and a caller seeding a strictly-after cursor from it (voice
   * catch-up) would refold the higher-id sibling it already had.
   */
  async getLastByThread(threadId: string): Promise<MessageRow | null> {
    return this.queryOne<MessageRow>(
      `${this.messageSelect} WHERE m.thread_id = $1 ORDER BY m.created_at DESC, m.id DESC LIMIT 1`,
      [threadId]
    );
  }

  /**
   * Whether anyone but `selfAgentId` posted in the thread after `since` (ISO):
   * a person (a user-role message from the app or an external member, not an
   * automation's own wake) or another agent (not the ghost agent a hook sends
   * as), plus any message stamped `capped` (metadata.chain), whoever sent it.
   * Narration never counts. An unattended run that sees one may not
   * auto-approve: the call may be acting on someone else's words.
   */
  async hasMessageFromOthersSince(
    threadId: string,
    since: string,
    selfAgentId: string,
    ghostAgentId: string
  ): Promise<boolean> {
    const row = await this.queryOne<{ found: boolean }>(
      `SELECT EXISTS (
         SELECT 1 FROM ${this.qualifiedTable}
          WHERE thread_id = $1
            AND message_type = 'message'
            AND created_at > $2::timestamptz
            AND (
              (role = 'user' AND NOT (COALESCE(metadata, '{}'::jsonb) ? 'automation'))
              OR (role = 'assistant' AND agent_id IS NOT NULL
                  AND agent_id <> $3 AND agent_id <> $4)
              -- A capped send counts whoever sent it (a hook as the ghost, or
              -- this agent itself), so reading it back on a later turn of the
              -- wave still stops approvals.
              OR (metadata->'chain'->>'capped') = 'true'
            )
       ) AS found`,
      [threadId, since, selfAgentId, ghostAgentId]
    );
    return row?.found === true;
  }

  /** Count messages in a thread. */
  async countByThreadId(threadId: string): Promise<number> {
    const row = await this.queryOne<{ count: string }>(
      `SELECT COUNT(*)::text AS count FROM ${this.qualifiedTable} WHERE thread_id = $1`,
      [threadId]
    );
    return row ? parseInt(row.count, 10) : 0;
  }

  /**
   * Count user-authored messages in a thread (agent replies are `assistant`
   * role and excluded). Used to detect a thread's opening message robustly —
   * the count stays 1 across the whole opening wave no matter how many agents
   * reply, so it fires for every agent on the opener.
   */
  async countUserMessagesByThreadId(threadId: string): Promise<number> {
    // Only real user sends count — `thread_event` rows are role='user' machine
    // narration (author-less; see createEvent) and must not inflate the opener
    // detection that keys on this count === 1.
    const row = await this.queryOne<{ count: string }>(
      `SELECT COUNT(*)::text AS count FROM ${this.qualifiedTable} WHERE thread_id = $1 AND role = 'user' AND message_type = 'message'`,
      [threadId]
    );
    return row ? parseInt(row.count, 10) : 0;
  }

  /**
   * Insert an author-less `thread_event` row: role='user', no user_id and no
   * agent_id, message_type='thread_event'. This is machine narration of
   * thread-variable state (roster/dispatch-mode changes, the turn-zero line),
   * not something any principal "said" — hence author-less, which the
   * messages_role_matches_author CHECK permits (its first disjunct is
   * "user_id IS NULL AND agent_id IS NULL"). Bypasses the role/author guard in
   * create() on purpose. `eventKind` is stashed on metadata so callers can
   * make emission idempotent (e.g. one 'thread_started' per thread).
   */
  async createEvent(input: {
    threadId: string;
    content: string;
    eventKind: string;
    id?: string;
    metadata?: Record<string, unknown>;
    /**
     * Agent-private narration: only this agent's payload carries the row
     * (see `visibleToAgentId` on MessageRow). Omitted = every agent sees it.
     */
    visibleToAgentId?: string | null;
  }): Promise<MessageRow> {
    const id = input.id ?? generateId('message');
    await Nodes.ensure(id, NODE_KIND.MESSAGE);
    return super.create({
      id,
      threadId: input.threadId,
      role: 'user',
      userId: null,
      agentId: null,
      content: input.content,
      messageType: 'thread_event',
      metadata: { ...input.metadata, event_kind: input.eventKind },
      ...(input.visibleToAgentId ? { visibleToAgentId: input.visibleToAgentId } : {}),
    } as unknown as MessageInsert);
  }

  /**
   * The newest reply `agentId` posted in a thread (a message or a question,
   * never narration or tool rows). Subagent helpers report through it.
   * `skipRunErrors` also passes over the error bubble a failed run leaves
   * (`metadata.run_error`, persistRunErrorMessage): it is not the agent's work.
   */
  async findLatestAgentReply(
    threadId: string,
    agentId: string,
    opts: { skipRunErrors?: boolean } = {}
  ): Promise<MessageRow | null> {
    const runErrors = opts.skipRunErrors ? `AND NOT (m.metadata ? 'run_error')` : '';
    return this.queryOne<MessageRow>(
      `${this.messageSelect}
        WHERE m.thread_id = $1 AND m.agent_id = $2 AND m.role = 'assistant'
          AND m.message_type IN ('message', 'question') ${runErrors}
        ORDER BY m.created_at DESC, m.id DESC
        LIMIT 1`,
      [threadId, agentId]
    );
  }

  /**
   * Agent-private `thread_event` rows of `startKind` written since `since`
   * that no `endKind` row in the same thread answers (the same
   * `metadata[pairKey]` value), oldest first. Background shell jobs use it at
   * boot to find the jobs a restart cut off. Bounded by the created_at index
   * and `limit`; the answer lookup is per thread.
   */
  async listUnansweredEvents(input: {
    startKind: string;
    endKind: string;
    pairKey: string;
    since: string;
    limit?: number;
  }): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `${this.messageSelect}
        WHERE m.created_at >= $4
          AND m.message_type = 'thread_event'
          AND m.visible_to_agent_id IS NOT NULL
          AND m.metadata ->> 'event_kind' = $1
          AND NOT EXISTS (
            SELECT 1 FROM ${this.qualifiedTable} e
             WHERE e.thread_id = m.thread_id
               AND e.message_type = 'thread_event'
               AND e.metadata ->> 'event_kind' = $2
               AND e.metadata ->> $3 = m.metadata ->> $3
          )
        ORDER BY m.created_at ASC, m.id ASC
        LIMIT $5`,
      [input.startKind, input.endKind, input.pairKey, input.since, input.limit ?? 200]
    );
  }

  /** Whether a `thread_event` of the given kind already exists on the thread. */
  async hasEventOfKind(threadId: string, eventKind: string): Promise<boolean> {
    const row = await this.queryOne<{ exists: boolean }>(
      `SELECT EXISTS (
         SELECT 1 FROM ${this.qualifiedTable}
         WHERE thread_id = $1 AND message_type = 'thread_event'
           AND metadata ->> 'event_kind' = $2
       ) AS exists`,
      [threadId, eventKind]
    );
    return row?.exists === true;
  }

  /**
   * Store NLP-extracted entity terms (people/places/orgs from the on-device
   * Apple NLTagger helper, see apps/server/src/services/nlp).
   *
   * This writes `search_entity_terms`, not `search_text`: `search_text` is a
   * stored generated column over `content || ' ' || search_entity_terms`, so
   * the database maintains it for every row. Enrichment is purely additive:
   * it widens recall beyond a literal content match, and its absence costs
   * nothing.
   */
  async updateSearchEntityTerms(messageId: string, entityTerms: readonly string[]): Promise<void> {
    await this.pool.query(
      `UPDATE ${this.qualifiedTable}
          SET search_entity_terms = $2
        WHERE id = $1`,
      [messageId, entityTerms.join(' ')]
    );
  }

  /**
   * Persist a per-agent context pack onto a message's metadata, write-once.
   * Stored at `metadata.contextPacks[agentId]`; never overwrites an existing
   * pack, so an agent's perceived prefix stays byte-identical across turns =
   * prompt-cache safe. Other agents' packs and other metadata keys are
   * preserved (nested jsonb merge). No-op if the agent already has a pack.
   */
  async setContextPackOnce(messageId: string, agentId: string, pack: string): Promise<boolean> {
    const result = await this.pool.query(
      `UPDATE ${this.qualifiedTable}
          SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
                'contextPacks',
                COALESCE(metadata -> 'contextPacks', '{}'::jsonb)
                  || jsonb_build_object($2::text, $3::text)
              )
        WHERE id = $1
          AND (metadata #> ARRAY['contextPacks', $2::text]) IS NULL`,
      [messageId, agentId, pack]
    );
    return (result.rowCount ?? 0) > 0;
  }

  /**
   * Hard-delete every message in a thread via the nodes spine — cascades take
   * the messages rows, their embeddings (embeddings.node_id → nodes ON DELETE
   * CASCADE) and any links touching them. The thread's runs/activity are
   * deleted by the shared execution-purge transaction, since turn replay would
   * otherwise resurrect them. Returns the number removed. Powers the "Clear
   * thread" action.
   */
  async deleteByThread(threadId: string, runner?: NodeRunner): Promise<number> {
    const r = runner ?? this.pool;
    const { rows } = await r.query<{ id: string }>(
      `SELECT id FROM ${this.qualifiedTable} WHERE thread_id = $1`,
      [threadId]
    );
    if (rows.length === 0) return 0;
    await Nodes.deleteByIds(
      rows.map((row) => row.id),
      r
    );
    return rows.length;
  }

  /** Override findById to project from messageSelect (JOIN public.nodes). */
  override async findById(id: string): Promise<MessageRow | null> {
    return this.queryOne<MessageRow>(`${this.messageSelect} WHERE m.id = $1`, [id]);
  }

  /**
   * Override base Model.list so the custom projection is used.
   */
  override async list(opts?: { limit?: number; offset?: number }): Promise<MessageRow[]> {
    const limit = opts?.limit ?? 100;
    const offset = opts?.offset ?? 0;
    return this.query<MessageRow>(
      `${this.messageSelect} ORDER BY m.created_at DESC LIMIT $1 OFFSET $2`,
      [limit, offset]
    );
  }

  async create(input: MessageInsert): Promise<MessageRow> {
    // Role is required and must agree with authorship. The DB CHECK
    // `messages_role_matches_author` will also reject mismatches, but we
    // surface the error here with a clearer message before hitting Postgres.
    if (input.role !== 'user' && input.role !== 'assistant') {
      throw new Error(
        `MessageModel.create: role must be 'user' or 'assistant', got ${JSON.stringify(input.role)}. ` +
          "'system' is not supported on public.messages (no rows exist; the role CHECK rejects it). " +
          'Add it to the DB CHECK if/when system messages become real.'
      );
    }
    if (input.role === 'user' && !input.userId) {
      throw new Error("MessageModel.create: role='user' requires userId to be set.");
    }
    if (input.role === 'assistant' && !input.agentId) {
      throw new Error("MessageModel.create: role='assistant' requires agentId to be set.");
    }

    // public.messages.id FKs to public.nodes.id; the node row must exist first.
    const id = input.id ?? generateId('message');
    await Nodes.ensure(id, NODE_KIND.MESSAGE);

    // Fold surfaced metadata keys into metadata jsonb. `role` flows through
    // unchanged — it's a real column on public.messages.
    const folded = this.foldMetadata({ ...input, id } as unknown as Record<string, unknown>);
    return super.create(folded as unknown as MessageInsert);
  }

  async update(id: string, input: MessageUpdate): Promise<MessageRow | null> {
    const folded = this.foldMetadata(input as unknown as Record<string, unknown>);
    return super.update(id, folded as unknown as MessageUpdate);
  }

  /**
   * List messages on a thread in chronological order.
   * Ordering uses public.messages.created_at.
   */
  async listByThread(threadId: string): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `${this.messageSelect} WHERE m.thread_id = $1 ORDER BY m.created_at ASC`,
      [threadId]
    );
  }

  /**
   * Most recent N messages on a thread, returned in descending order.
   */
  async getRecentDescending(threadId: string, limit: number): Promise<MessageRow[]> {
    return this.query<MessageRow>(
      `${this.messageSelect} WHERE m.thread_id = $1 ORDER BY m.created_at DESC LIMIT $2`,
      [threadId, limit]
    );
  }
}

export const Messages = new MessageModelClass();
